+      } else {
+        config.input.removeAttribute('aria-describedby');
+      }
+    }
+
+    function validateField(config) {
+      const message = config.getMessage(config.input.value, config.input);
+      const field = config.input.closest('.form-field');
+      const hasError = Boolean(message);
+
+      config.error.textContent = message;
+      config.error.hidden = !hasError;
+      config.input.setAttribute('aria-invalid', hasError ? 'true' : 'false');
+      field.classList.toggle('invalid', hasError);
+      updateDescriptions(config, hasError);
+
+      return !hasError;
+    }
