  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <main id="maincontent" tabindex="-1">
    <div class="support-shell">
      <section class="hero" aria-labelledby="page-title">
        <div>
          <p class="eyebrow">Support</p>
          <h1 id="page-title">Talk to our support team</h1>
          <p>
            Share the details and we will get back to you with the fastest path forward.
            Required fields are marked with <span aria-hidden="true">*</span><span class="sr-only"> an asterisk</span>.
          </p>
        </div>

        <ul class="feature-list" aria-label="Support benefits">
          <li><strong>Fast routing</strong>Your request goes straight to the right specialist.</li>
          <li><strong>Human follow-up</strong>Get a clear response from a member of our team.</li>
          <li><strong>Flexible contact</strong>Add a phone number if you want a call back.</li>
        </ul>
      </section>

      <section class="contact-card" aria-labelledby="contact-form-title">
        <h2 id="contact-form-title">Send a support request</h2>
        <p>Use the form below and we will follow up by email, or by phone if you include one.</p>

        <form id="support-form" novalidate>
          <div class="form-field" data-field="full-name">
            <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
            <input
              id="full-name"
              name="full-name"
              type="text"
              autocomplete="name"
              required
              aria-required="true"
            >
            <p id="full-name-error" class="field-error" hidden></p>
          </div>

          <div class="form-field" data-field="email">
            <label for="email">Email address <span class="required-mark" aria-hidden="true">*</span></label>
            <input
              id="email"
              name="email"
              type="email"
              autocomplete="email"
              inputmode="email"
              required
              aria-required="true"
            >
            <p id="email-error" class="field-error" hidden></p>
          </div>

          <div class="form-field" data-field="phone">
            <label for="phone">Phone number <span class="field-help">(optional)</span></label>
            <input
              id="phone"
              name="phone"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phone-help"
            >
            <p id="phone-help" class="field-help">Expected format: use digits only, for example 555-123-4567.</p>
            <p id="phone-error" class="field-error" hidden></p>
          </div>

          <p id="form-status" class="status-message" aria-live="polite" hidden></p>

          <button type="submit">Submit request</button>
        </form>
      </section>
    </div>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const statusMessage = document.getElementById('form-status');

    const fieldConfigs = {
      'full-name': {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        getMessage(value) {
          return value.trim() ? '' : 'Error: Enter your full name.';
        }
      },
      email: {
        input: document.getElementById('email'),
        error: document.getElementById('email-error'),
        getMessage(value, input) {
          if (!value.trim()) {
            return 'Error: Enter your email address.';
          }

          return input.validity.typeMismatch ? 'Error: Enter a valid email address, such as name@example.com.' : '';
        }
      },
      phone: {
        input: document.getElementById('phone'),
        error: document.getElementById('phone-error'),
        helpId: 'phone-help',
        getMessage(value) {
          if (!value.trim()) {
            return '';
          }

          const phonePattern = /^[0-9()\-\s+.]+$/;
          return phonePattern.test(value)
            ? ''
            : 'Error: Use digits only, for example 555-123-4567.';
        }
      }
    };

    function updateDescriptions(config, hasError) {
      const describedBy = [];

      if (config.helpId) {
        describedBy.push(config.helpId);
      }

      if (hasError) {
        describedBy.push(config.error.id);
      }

      if (describedBy.length > 0) {
        config.input.setAttribute('aria-describedby', describedBy.join(' '));
      } else {
        config.input.removeAttribute('aria-describedby');
      }
    }

    function validateField(config) {
      const message = config.getMessage(config.input.value, config.input);
      const field = config.input.closest('.form-field');
      const hasError = Boolean(message);

      config.error.textContent = message;
      config.error.hidden = !hasError;
      config.input.setAttribute('aria-invalid', hasError ? 'true' : 'false');
      field.classList.toggle('invalid', hasError);
      updateDescriptions(config, hasError);

      return !hasError;
    }

    Object.values(fieldConfigs).forEach((config) => {
      config.input.addEventListener('input', () => {
        if (!config.error.hidden) {
          validateField(config);
        }

        if (!statusMessage.hidden) {
          statusMessage.hidden = true;
          statusMessage.textContent = '';
        }
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const validationResults = Object.values(fieldConfigs).map((config) => ({
        input: config.input,
        valid: validateField(config)
      }));

      const firstInvalid = validationResults.find((result) => !result.valid);

      if (firstInvalid) {
        statusMessage.textContent = 'Please correct the highlighted fields and submit again.';
        statusMessage.hidden = false;
        firstInvalid.input.focus();
        return;
      }

      statusMessage.textContent = 'Your support request is ready to send. A team member will follow up soon.';
      statusMessage.hidden = false;
      form.reset();
      Object.values(fieldConfigs).forEach((config) => {
        config.error.hidden = true;
        config.error.textContent = '';
        config.input.setAttribute('aria-invalid', 'false');
        config.input.closest('.form-field').classList.remove('invalid');
        updateDescriptions(config, false);
      });
    });
  </script>
